style.css:
@-moz-document domain("facebook.com") {
/* 1. KHAI BÁO BIẾN TOÀN CỤC (Biến màu Dark Mode & Kính mờ) */
    :root, .__fb-dark-mode {
        --fb-bg: #09090b !important;
        --glass-bg: rgba(25, 25, 30, 0.45) !important;
        --glass-border: 1px solid rgba(255, 255, 255, 0.08) !important;
        --glass-shadow: 0 20px 40px rgba(0, 0, 0, 0.4) !important;
        --radius-lg: 24px !important;
        --radius-pill: 999px !important;
        --text-primary: #f8fafc !important;
        --text-secondary: #94a3b8 !important;
        --apple-font: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, sans-serif !important;
        
        /* Ghi đè biến mặc định của FB */
        --surface-background: transparent !important;
        --card-background: var(--glass-bg) !important;
        --card-background-flat: var(--glass-bg) !important;
        --nav-bar-background: rgba(15, 15, 20, 0.65) !important;
        --primary-button-background: rgba(255, 255, 255, 0.1) !important;
    }

    /* 2. ĐỒNG BỘ FONT CHỮ APPLE & NỀN TỔNG THỂ */
    body {
        font-family: var(--apple-font) !important;
        background-color: var(--fb-bg) !important;
        background-image: 
            radial-gradient(circle at 15% 50%, rgba(0, 122, 255, 0.15) 0%, transparent 50%),
            radial-gradient(circle at 85% 30%, rgba(255, 45, 85, 0.12) 0%, transparent 50%) !important;
        background-attachment: fixed !important;
        color: var(--text-primary) !important;
    }

    /* 3. THANH ĐIỀU HƯỚNG TRÊN CÙNG (TOP NAVIGATION BAR) */
    div[role="banner"] {
        background: var(--nav-bar-background) !important;
        backdrop-filter: blur(30px) saturate(200%) !important;
        -webkit-backdrop-filter: blur(30px) saturate(200%) !important;
        border-bottom: var(--glass-border) !important;
        box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2) !important;
    }

    /* Bo tròn thanh tìm kiếm thành dạng Pill (viên thuốc) */
    label[aria-label="Tìm kiếm trên Facebook"],
    input[type="search"],
    div[role="search"] {
        border-radius: var(--radius-pill) !important;
        background: rgba(255, 255, 255, 0.08) !important;
        border: 1px solid rgba(255, 255, 255, 0.05) !important;
    }

    /* 4. CÁC BÀI VIẾT / BẢNG TIN (FEED CARDS) */
    div[role="article"],
    div[data-pagelet^="FeedUnit_"],
    div[data-pagelet="Stories"] > div,
    div[data-pagelet="VideoFBMiddletier"] {
        background: var(--glass-bg) !important;
        backdrop-filter: blur(25px) !important;
        -webkit-backdrop-filter: blur(25px) !important;
        border-radius: var(--radius-lg) !important;
        border: var(--glass-border) !important;
        box-shadow: var(--glass-shadow) !important;
        margin-bottom: 20px !important;
        overflow: hidden !important;
        transition: transform 0.3s cubic-bezier(0.25, 1, 0.5, 1) !important;
    }

    /* Hiệu ứng nảy (Spring Physics) khi hover vào bài viết */
    div[role="article"]:hover {
        transform: translateY(-2px) scale(1.005) !important;
        border: 1px solid rgba(255, 255, 255, 0.15) !important;
    }

    /* 5. CỘT TRÁI & PHẢI (SIDEBARS & CHAT) */
    div[role="navigation"], 
    div[data-pagelet="RightRail"] {
        background: transparent !important;
    }

    /* Khung chat pop-up góc phải */
    div[data-pagelet="ChatTab"] > div {
        background: rgba(20, 20, 25, 0.75) !important;
        backdrop-filter: blur(30px) !important;
        -webkit-backdrop-filter: blur(30px) !important;
        border-radius: 20px 20px 0 0 !important;
        border: var(--glass-border) !important;
        border-bottom: none !important;
        box-shadow: var(--glass-shadow) !important;
    }

    /* 6. NÚT BẤM (BUTTONS) & MENU THẢ XUỐNG */
    div[role="button"], 
    div[role="menu"] {
        border-radius: 16px !important;
    }
    
    div[role="menu"] {
        background: rgba(30, 30, 35, 0.85) !important;
        backdrop-filter: blur(40px) saturate(150%) !important;
        -webkit-backdrop-filter: blur(40px) saturate(150%) !important;
        border: var(--glass-border) !important;
        box-shadow: 0 25px 50px rgba(0,0,0,0.5) !important;
    }

    /* 7. CUSTOM THANH CUỘN (SCROLLBAR) */
    ::-webkit-scrollbar {
        width: 10px !important;
        background: transparent !important;
    }
    ::-webkit-scrollbar-thumb {
        background: rgba(255, 255, 255, 0.2) !important;
        border-radius: 20px !important;
        border: 2px solid var(--fb-bg) !important;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: rgba(255, 255, 255, 0.4) !important;
    }
}
